WITH joined AS (SELECT src.*, e.job_title AS employee_job_title FROM employees src LEFT JOIN employees e ON src.manager_id = e.id) SELECT CASE WHEN salary >= 150000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, APPROX_PERCENTILE(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, AVG(salary) FILTER (WHERE level = 'L4') AS l4_avg_salary, ROUND(AVG(salary), 2) AS avg_salary, COUNT(*) FILTER (WHERE job_title = 'Engineer') AS engineer_rows, COUNT(*) AS cnt, GROUPING(CASE WHEN salary >= 150000 THEN 'HIGH' ELSE 'LOW' END) AS gid FROM joined GROUP BY CUBE (CASE WHEN salary >= 150000 THEN 'HIGH' ELSE 'LOW' END);
